    billing: ['Invoices, payments and insurer claims tied to each appointment, so the books close themselves.', [['ri-bill-line', 'Invoice on checkout', 'Raised as soon as the visit ends'], ['ri-bank-card-line', 'Take payment', 'Card, link or account in one flow'], ['ri-file-shield-line', 'Insurer claims', 'Pre-authorisations and claims tracked']]],
    'documents-and-forms': ['Templates, consent forms and letters that fill themselves from the record and land back on it signed.', [['ri-file-edit-line', 'Smart templates', 'Patient details merged automatically'], ['ri-quill-pen-line', 'e-Signatures', 'Patients sign on any device'], ['ri-folder-shield-2-line', 'Filed for you', 'Signed copies saved to the record']]],
    automations: ['Set up “when this happens, do that” rules — follow-ups, reminders and hand-offs that run on their own.', [['ri-flow-chart', 'Visual builder', 'Triggers, conditions and actions'], ['ri-mail-send-line', 'Timed messages', 'Nudge leads at the right moment'], ['ri-history-line', 'Full history', 'See every run and what it did']]],
    'tags-and-sources': ['Tag contacts and track where every lead comes from, so you know which channels actually pay off.', [['ri-price-tag-3-line', 'Custom tags', 'Group people your way'], ['ri-links-line', 'Source tracking', 'Ads, referrals and walk-ins attributed'], ['ri-pie-chart-2-line', 'ROI by channel', 'Bookings and revenue per source']]],
    'staff-management': ['Your team’s profiles, contracts, qualifications and documents, kept current in one place.', [['ri-team-line', 'Staff directory', 'Roles, sites and contacts'], ['ri-award-line', 'Qualifications', 'Registrations and expiry dates tracked'], ['ri-file-user-line', 'HR documents', 'Contracts and right-to-work in one file']]],
    'rota-management': ['Build rotas that respect availability, skills and leave — and publish them to everyone’s phone.', [['ri-calendar-schedule-line', 'Drag-and-drop rota', 'Fill sessions in minutes'], ['ri-user-settings-line', 'Skill-aware', 'Right clinician in the right session'], ['ri-smartphone-line', 'Instant updates', 'Changes pushed to the team']]],
    'activity-tracker': ['See who’s clocked in, what they’re working on and where time goes, without the spreadsheets.', [['ri-timer-line', 'Clock in / out', 'From the clinic or on the move'], ['ri-bar-chart-box-line', 'Time insights', 'Hours by person, role and site'], ['ri-alarm-warning-line', 'Exceptions', 'Missed punches flagged automatically']]],
    'leaves-management': ['Request, approve and plan leave with the rota in view, so cover is never a surprise.', [['ri-calendar-event-line', 'Self-service requests', 'Staff apply from their phone'], ['ri-checkbox-circle-line', 'One-tap approvals', 'With rota clashes highlighted'], ['ri-sun-line', 'Allowance tracking', 'Balances always up to date']]],
    compliance: ['Mandatory training, checks and policies for every staff member, with reminders before anything lapses.', [['ri-graduation-cap-line', 'Training matrix', 'Who’s done what, and what’s due'], ['ri-shield-check-line', 'DBS & registrations', 'Expiry dates tracked for you'], ['ri-file-text-line', 'Policy sign-off', 'Read-and-sign with an audit trail']]],
    'patient-comms': ['Message patients by SMS, email or WhatsApp from one place, with templates and replies on the record.', [['ri-chat-smile-2-line', 'Every channel', 'SMS, email and WhatsApp together'], ['ri-file-copy-2-line', 'Templates', 'Consistent, on-brand messages'], ['ri-archive-drawer-line', 'Saved to record', 'Every message kept with the patient']]],
